save(195,dict(paragraphs=["Tandra Mishra writes poetry in English and Bengali. A contributor biography in Literary Vibes places her in Raiganj, West Bengal, records her postgraduate study of English and identifies Oh Father! as her first poetry collection. Her writing brings questions of women's freedom and dignity into a wider concern with social life.","In her Kabita Live poem I am a Girl, the repeated declaration of identity gathers strength through a succession of roles: worker, artist, soldier, caregiver and creator. Public achievement sits beside the less acknowledged labour of sustaining a home. The poem's direct address asks that care and courage be recognised together, rather than treating tenderness as the opposite of power."],sources=[source('Literary Vibes — Tandra Mishra contributor biography','https://positivevibes.today/article/newsview/495','Raiganj, English postgraduate study, first collection Oh Father! and writing on women’s empowerment.','search_index_full_biography')],identity_match='Exact name, Raiganj location, English study and Oh Father! agree with captured biography.',poems_read=[dict(id=183,title='I am a Girl',coverage='Complete original English poem',basis='Refrain, professional roles, domestic care, social contribution and final creator/protector/warrior sequence.')],limitations=['No publisher or library record for Oh Father! verified; no book card added.','FUREC award and organisational membership retained only in captured biography; no organiser corroboration obtained.'],search_queries=['"Tandra Mishra" "Oh Father"','"Tandra Mishra" poet Raiganj'],next_action='Author/editor to confirm book publication particulars and award details.'))
